CREATE TABLE tenants (id BIGINT PRIMARY KEY, name VARCHAR(160) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE branches (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, invoice_required BOOLEAN NOT NULL DEFAULT FALSE, receipt_sequence BIGINT NOT NULL DEFAULT 0, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE employees (username VARCHAR(100) PRIMARY KEY, password_hash VARCHAR(200) NOT NULL, tenant_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, enabled BOOLEAN NOT NULL, UNIQUE(tenant_id,branch_id,username), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE employee_permissions (username VARCHAR(100) NOT NULL, permission VARCHAR(80) NOT NULL, PRIMARY KEY(username,permission), FOREIGN KEY(username) REFERENCES employees(username));
CREATE TABLE registers (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, UNIQUE(tenant_id,branch_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE pos_sessions (id VARCHAR(36) PRIMARY KEY, tenant_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, cashier VARCHAR(100) NOT NULL, register_id BIGINT NOT NULL, state VARCHAR(16) NOT NULL, opening_float DECIMAL(19,2) NOT NULL CHECK(opening_float>=0), active_register BIGINT GENERATED ALWAYS AS (CASE WHEN state='OPEN' THEN register_id ELSE NULL END), UNIQUE(tenant_id,active_register), UNIQUE(tenant_id,branch_id,cashier,id), FOREIGN KEY(tenant_id,branch_id,cashier) REFERENCES employees(tenant_id,branch_id,username), FOREIGN KEY(tenant_id,branch_id,register_id) REFERENCES registers(tenant_id,branch_id,id));
CREATE TABLE products (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, sku VARCHAR(80) NOT NULL, barcode VARCHAR(80), name VARCHAR(160) NOT NULL, price DECIMAL(19,2) NOT NULL CHECK(price>=0), tax_rate DECIMAL(5,2) NOT NULL CHECK(tax_rate>=0 AND tax_rate<=100), published BOOLEAN NOT NULL, UNIQUE(tenant_id,id), UNIQUE(tenant_id,sku), FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE inventory (tenant_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL CHECK(quantity>=0), PRIMARY KEY(tenant_id,branch_id,product_id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE orders (id VARCHAR(36) PRIMARY KEY, tenant_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, cashier VARCHAR(100) NOT NULL, session_id VARCHAR(36) NOT NULL, customer_id BIGINT NULL, sales_channel VARCHAR(16) NOT NULL CHECK(sales_channel='IN_STORE'), idempotency_key VARCHAR(80) NOT NULL, request_hash VARCHAR(64) NOT NULL, total DECIMAL(19,2) NOT NULL, cash_received DECIMAL(19,2) NOT NULL, change_given DECIMAL(19,2) NOT NULL, receipt_number BIGINT NOT NULL, tax_invoice BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(tenant_id,id), UNIQUE(tenant_id,idempotency_key), UNIQUE(tenant_id,branch_id,receipt_number), CHECK(cash_received-change_given=total), FOREIGN KEY(tenant_id,branch_id,cashier,session_id) REFERENCES pos_sessions(tenant_id,branch_id,cashier,id));
CREATE TABLE order_items (tenant_id BIGINT NOT NULL, order_id VARCHAR(36) NOT NULL, product_id BIGINT NOT NULL, name VARCHAR(160) NOT NULL, quantity INT NOT NULL CHECK(quantity>0), price DECIMAL(19,2) NOT NULL, tax_rate DECIMAL(5,2) NOT NULL, tax DECIMAL(19,2) NOT NULL, total DECIMAL(19,2) NOT NULL, PRIMARY KEY(tenant_id,order_id,product_id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE inventory_ledger (tenant_id BIGINT NOT NULL, branch_id BIGINT NOT NULL, product_id BIGINT NOT NULL, order_id VARCHAR(36) NOT NULL, quantity_delta INT NOT NULL, PRIMARY KEY(tenant_id,order_id,product_id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id), FOREIGN KEY(tenant_id,branch_id,product_id) REFERENCES inventory(tenant_id,branch_id,product_id));
CREATE TABLE pos_audit (id VARCHAR(36) PRIMARY KEY, tenant_id BIGINT NOT NULL, actor VARCHAR(100) NOT NULL, action VARCHAR(40) NOT NULL, resource_id VARCHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenant_id) REFERENCES tenants(id));
